function getYellowaiTranslation(key, lang) {
  if (yellowaiTranslations[lang] && yellowaiTranslations[lang][key]) {
    return yellowaiTranslations[lang][key];
  }
  if (yellowaiTranslations.en && yellowaiTranslations.en[key]) {
    return yellowaiTranslations.en[key];
  }
  return null;
}

function applyYellowaiTranslations(lang) {
  console.log(`🔥 Applying yellowai translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.yellowai.') || key.startsWith('review.common.'))) {
      const translation = getYellowaiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} yellowai translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyYellowaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyYellowaiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyYellowaiTranslations(currentLang);
}

console.log('✅ yellowai i18n loaded');
